    def worker():
        out, err = proc.communicate()
        result_container["out"] = out
        result_container["err"] = err
    t = threading.Thread(target=worker)
    t.start()
    t.join(timeout)
    if t.is_alive():
        proc.terminate()
        try:
            proc.wait(timeout=5)
        except Exception:
            pass
        return "Terminating process due to timeout."
    return "Script executed successfully."
